--- from: Assets/BundleResources/Arts/GachaponRes/120000/Gachapon120000.prefab > name: Gachapon120000
---@class GachaponStepDiscountEntry
---@field Env                           	GachaponStepDiscountEntry               
---@field controller                    	Engine.Modules.LuaBehaviour             
---@field TextTime                      	UnityEngine.RectTransform               	@ 0    
---@field TxtTips                       	UnityEngine.RectTransform               	@ 1    
---@field Root                          	UnityEngine.RectTransform               	@ 2    
---@field Cell                          	UnityEngine.RectTransform               	@ 3    
---@field BtnStepNode                   	UnityEngine.RectTransform               	@ 4    
---@field Unlock                        	UnityEngine.RectTransform               	@ 5    
---@field Lock                          	UnityEngine.RectTransform               	@ 6    
---@field originalIcon                  	UnityEngine.RectTransform               	@ 7    
---@field originalPrice                 	UnityEngine.RectTransform               	@ 8    
---@field NowIcon                       	UnityEngine.RectTransform               	@ 9    
---@field NowPrice                      	UnityEngine.RectTransform               	@ 10   
local GachaponStepDiscountEntry = Class("GachaponStepDiscountEntry")
---@type GachaponUtils
local GachaponUtils = import('Game.Gachapon.GachaponUtils')
local CellPath = "Game.Gachapon.GachaponStepDiscountEntryCell"

function GachaponStepDiscountEntry:__init()
    self.pool = nil
    self.callBack = nil
    self.nodeEnv = {}
end

function GachaponStepDiscountEntry:__delete()
    self.pool = nil
    self.callBack = nil
    self.nodeEnv = nil
    self.controller = nil
end

function GachaponStepDiscountEntry:Awake()
    SetButtonAction(self.BtnStepNode,Bind(self,self.OnBtnStepNodeClick))

    local env = CfUtils.GetLuaScr(self.Cell.gameObject,CellPath)
    if env then
        table.insert(self.nodeEnv,env)
    end
end

function GachaponStepDiscountEntry:SetCallBack(cb)
    self.callBack = cb
end

function GachaponStepDiscountEntry:RefreshShow(pool)
    self.pool = pool
    if isNotNull(self.pool) then
        self:RefreshTimeShow()
        self:RefreshCurrencyShow()
        self:RefreshCellShow()
        self:RefreshTipsShow()
        self:RefreshBtnState()
        self:RefreshImgRole()
    end
end

function GachaponStepDiscountEntry:RefreshTipsShow()
    CfUtils.FillText(self.TxtTips,localize("出现的SSR只有当前_num_位！",{_num_ = self.ssrNum}))
end

function GachaponStepDiscountEntry:RefreshCurrencyShow()
    local goodsVo =  GoodsConfMgr:GetInstance():GetGoodsVoById(self.pool.tenConsume.goodsId)
    if isNotNull(goodsVo) then
        CfUtils.FillImage(self.originalIcon, goodsVo.photoPath)
        CfUtils.FillImage(self.NowIcon, goodsVo.photoPath)
    end

    CfUtils.FillText(self.originalPrice,self.pool.activity.originalPrice.num)
    CfUtils.FillText(self.NowPrice,self.pool.tenConsume.num)

    local isHide = checkNumber(self.pool.activity.originalPrice.num) == checkNumber(self.pool.tenConsume.num)
    CfUtils.SetActive(self.Spend.gameObject,not isHide)
end

function GachaponStepDiscountEntry:RefreshCellShow()
    local allVos = GachaponUtils.GetStepPoolVos(self.pool.poolId)
    self.ssrNum = allVos[1].ssrNum
    for i, v in pairs(allVos) do
        if self.nodeEnv[i] then
            self.nodeEnv[i]:PlayDailyAni(i)
            self.nodeEnv[i]:RefreshShow(v , self.pool)
        else
            local go = CfUtils.InstantiateGo(self.Cell.gameObject,self.Root.gameObject,false)
            if isNotNull(go) then
                go.name = "Cell"..i
                local env = CfUtils.GetLuaScr(go,CellPath)
                if env then
                    env:PlayDailyAni(i)
                    env:RefreshShow(v , self.pool)
                    self.nodeEnv[i] = env
                end
            end
        end
    end
end

function GachaponStepDiscountEntry:RefreshTimeShow()
    local pool = self.pool
    if (pool:IsValidActivity() and checkInt(pool.activity.endRemainTime) <= 0) or (pool.remainSeconds == 0) then
        if pool:IsValidActivity() then
            CfUtils.FillText(self.TextTime, os.date("%Y.%m.%d", pool.activity.closeTime))
        else
            CfUtils.FillText(self.TextTime, '')
        end
    else
        if pool:IsValidActivity() then
            CfUtils.FillText(self.TextTime, GameUtils.CheckUTCTimeformat(GameUtils.l10nTimeData ("%Y.%m.%d", pool.activity.startTime).."-"..GameUtils.l10nTimeData("%Y.%m.%d %H:%M:%S",  pool.activity.endTime)))
        else
            CfUtils.FillText(self.TextTime, '')
        end
    end
end

function GachaponStepDiscountEntry:RefreshBtnState()
    local isUnLock = self.pool.isUnlock
    CfUtils.SetActive(self.Unlock.gameObject,isUnLock == 1)
    CfUtils.SetActive(self.Lock.gameObject,not (isUnLock == 1))

    local isComplete = self:IsComplete()
    CfUtils.SetActive(self.BtnStepNode.gameObject,not isComplete)
end

function GachaponStepDiscountEntry:RefreshImgRole()
    if self.ImgRole then
        if not string.isEmpty(self.pool.cardDrawingId) then
            local path = CS.ParseUtils.ParsePathNameByData(self.pool.cardDrawingId)
            CfUtils.FillImage(self.ImgRole,path)
        end
    end
end

function GachaponStepDiscountEntry:IsComplete()
    return self.pool.activity.stepNum > self.pool.activity.totalStepNum
end

function GachaponStepDiscountEntry:OnBtnStepNodeClick()
    if self:IsComplete() then
        return
    end

    if self.callBack then
        self.callBack()
    end
end

function GachaponStepDiscountEntry:OnDestroy()
    self.controller = nil --删除lua层引⽤到的c#对象否则不会产⽣c# gc回收到对象
    self:Delete()
end

return GachaponStepDiscountEntry